      WHEN transaction_id IS NULL THEN 'missing_payload_transaction_id'
      WHEN account_id IS NULL THEN 'missing_payload_account_id'
      WHEN merchant_id IS NULL THEN 'missing_payload_merchant_id'
      WHEN amount IS NULL THEN 'bad_type_payload_amount'
      WHEN currency IS NULL THEN 'missing_payload_currency'
