-- ---- transactions: latest state (valid rows only) ----
-- Windows run over the valid, de-duplicated events of one entity; the newest sequence wins.
CREATE DYNAMIC TABLE IF NOT EXISTS {db}.SILVER.silver_transactions
  TARGET_LAG = '5 minutes'
  WAREHOUSE = TRANSFORM_WH
  REFRESH_MODE = INCREMENTAL
AS
SELECT transaction_id, account_id, merchant_id, amount, currency, payment_method, channel, status, first_event_time, captured_at, last_event_time, last_sequence, schema_version
FROM (
  SELECT
    transaction_id AS transaction_id,
    account_id AS account_id,
    merchant_id AS merchant_id,
    amount AS amount,
    currency AS currency,
    payment_method AS payment_method,
    channel AS channel,
    event_type AS status,
    MIN(event_time) OVER (PARTITION BY transaction_id) AS first_event_time,
    MIN(CASE WHEN event_type = 'captured' THEN event_time END) OVER (PARTITION BY transaction_id) AS captured_at,
    event_time AS last_event_time,
    sequence AS last_sequence,
    schema_version AS schema_version,
    ROW_NUMBER() OVER (
      PARTITION BY transaction_id ORDER BY sequence DESC, event_time DESC, loaded_at DESC
    ) AS rn
  FROM {db}.SILVER.typed_transactions
  WHERE is_valid AND dup_rank = 1
)
WHERE rn = 1;

-- ---- transactions: rejected messages, kept with the reason and the original message ----
CREATE DYNAMIC TABLE IF NOT EXISTS {db}.QUARANTINE.rejected_transactions
  TARGET_LAG = '5 minutes'
  WAREHOUSE = TRANSFORM_WH
  REFRESH_MODE = INCREMENTAL
AS
SELECT event_id, event_type, entity_id, sequence, event_time, reject_reason, rejected_raw,
       source_file, source_row, loaded_at
FROM {db}.SILVER.typed_transactions
WHERE NOT is_valid;

