-- ---- disputes: latest state (valid rows only) ----
-- Windows run over the valid, de-duplicated events of one entity; the newest sequence wins.
CREATE DYNAMIC TABLE IF NOT EXISTS {db}.SILVER.silver_disputes
  TARGET_LAG = '5 minutes'
  WAREHOUSE = TRANSFORM_WH
  REFRESH_MODE = INCREMENTAL
AS
SELECT dispute_id, transaction_id, account_id, merchant_id, currency, reason_code, status, opened_at, opened_amount, resolved_at, resolved_amount, last_event_time, schema_version
FROM (
  SELECT
    dispute_id AS dispute_id,
    transaction_id AS transaction_id,
    account_id AS account_id,
    merchant_id AS merchant_id,
    currency AS currency,
    reason_code AS reason_code,
    CASE event_type WHEN 'dispute_opened' THEN 'opened' WHEN 'dispute_won' THEN 'won' ELSE 'lost' END AS status,
    MIN(CASE WHEN event_type = 'dispute_opened' THEN event_time END) OVER (PARTITION BY dispute_id) AS opened_at,
    MAX(CASE WHEN event_type = 'dispute_opened' THEN amount END) OVER (PARTITION BY dispute_id) AS opened_amount,
    MAX(CASE WHEN event_type IN ('dispute_won', 'dispute_lost') THEN event_time END) OVER (PARTITION BY dispute_id) AS resolved_at,
    MAX(CASE WHEN event_type IN ('dispute_won', 'dispute_lost') THEN amount END) OVER (PARTITION BY dispute_id) AS resolved_amount,
    event_time AS last_event_time,
    schema_version AS schema_version,
    ROW_NUMBER() OVER (
      PARTITION BY dispute_id ORDER BY sequence DESC, event_time DESC, loaded_at DESC
    ) AS rn
  FROM {db}.SILVER.typed_disputes
  WHERE is_valid AND dup_rank = 1
)
WHERE rn = 1;

